begin;
do $$
declare uid uuid:=gen_random_uuid();cu uuid:=gen_random_uuid();ed uuid:=gen_random_uuid();sid uuid;csid uuid;esid uuid;aal1 uuid;oid uuid:=gen_random_uuid();free_id uuid:=gen_random_uuid();key uuid:=gen_random_uuid();r jsonb;again jsonb;v int:=1;failed boolean;before_count int;today text:=(now()at time zone 'Asia/Kolkata')::date::text;readback jsonb;
begin
 insert into auth.users(id,email_confirmed_at) values(uid,now()),(cu,now()),(ed,now());insert into memocious_private.admin_users(user_id,role) values(uid,'owner'),(ed,'editor');
 sid:=public.memocious_session_open(repeat('1',64),repeat('2',64),uid,'admin','fixture','1');csid:=public.memocious_session_open(repeat('3',64),repeat('4',64),cu,'customer','fixture','1');esid:=public.memocious_session_open(repeat('5',64),repeat('6',64),ed,'admin','fixture','1');aal1:=public.memocious_session_open(repeat('7',64),repeat('8',64),uid,'admin','fixture','1');
 perform public.memocious_session_mfa(sid,repeat('9',64),repeat('a',64),'fixture');perform public.memocious_session_mfa(esid,repeat('b',64),repeat('c',64),'fixture');
 insert into memocious.orders(id,code,user_id,actor_session_id,source) values(oid,'GFT-2610-000001-0123456789AB',cu,csid,'product'),(free_id,'GFT-2610-000002-0123456789AB',cu,csid,'product');
 insert into memocious.order_events(order_id,actor_session_id,to_status,order_version,request_id) values(oid,csid,'inquiry',1,gen_random_uuid()),(free_id,csid,'inquiry',1,gen_random_uuid());
 execute 'set local role service_role';
 if jsonb_array_length(public.memocious_owner_orders(sid)->'orders')<>2 then raise exception 'Owner list';end if;
 failed:=false;begin perform public.memocious_owner_orders(esid);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Editor read';end if;
 failed:=false;begin perform public.memocious_owner_orders(aal1);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'aal1 read';end if;
 failed:=false;begin perform public.memocious_owner_order_action(csid,oid,1,key,'transition','{"status":"confirmed","reason":"x"}');exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Customer action';end if;
 failed:=false;begin perform public.memocious_owner_order_action(esid,oid,1,key,'transition','{"status":"confirmed","reason":"x"}');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Editor action';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,1,key,'transition','{"status":"confirmed","reason":"x","agreedTotalPaise":10000}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Confirmation without contact';end if;
 r:=public.memocious_owner_order_action(sid,oid,1,key,'transition','{"status":"confirmed","reason":"Genuine scope agreed","customerNote":"Agreed","agreedTotalPaise":10000,"contactName":"Fixture customer","phone":"12025550123"}');
 again:=public.memocious_owner_order_action(sid,oid,1,key,'transition','{"status":"confirmed","reason":"Genuine scope agreed","customerNote":"Agreed","agreedTotalPaise":10000,"contactName":"Fixture customer","phone":"12025550123"}');
 if r<>again or r->>'version'<>'2' then raise exception 'Matching replay';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,1,key,'transition','{"status":"cancelled","reason":"Changed retry"}');exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Changed key';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,1,gen_random_uuid(),'transition','{"status":"cancelled","reason":"stale"}');exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Stale version';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,2,gen_random_uuid(),'transition','{"status":"payment_received","reason":"No receipt"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Invented receipt';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,2,gen_random_uuid(),'receipt',jsonb_build_object('amountPaise',2000,'date',((now()at time zone 'Asia/Kolkata')::date+1)::text,'reference','future','reason','Future receipt'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Future payment facts';end if;
 key:=gen_random_uuid();
 r:=public.memocious_owner_order_action(sid,oid,2,key,'receipt',jsonb_build_object('amountPaise',2000,'date',today,'reference','PRIVATE receipt reference','reason','PRIVATE verified bank evidence','customerNote','Deposit recorded'));
 again:=public.memocious_owner_order_action(sid,oid,2,key,'receipt',jsonb_build_object('amountPaise',2000,'date',today,'reference','PRIVATE receipt reference','reason','PRIVATE verified bank evidence','customerNote','Deposit recorded'));
 if r<>again or r->>'status'<>'confirmed' then raise exception 'Receipt inferred status or duplicate';end if;
 if public.memocious_customer_orders(csid,'GFT-2610-000001-0123456789AB')::text like '%PRIVATE%' then raise exception 'Private payment facts leaked';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,3,gen_random_uuid(),'receipt',jsonb_build_object('amountPaise',2000,'date',today,'reference','PRIVATE receipt reference','reason','Accidental duplicate with a new key'));exception when unique_violation then failed:=true;end;if not failed then raise exception 'Duplicate reference accepted';end if;
 if public.memocious_owner_orders(sid,'GFT-2610-000001-0123456789AB')->'order'->>'version'<>'3' then raise exception 'Failed money insert did not roll back order/event';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,3,gen_random_uuid(),'receipt',jsonb_build_object('amountPaise',9000,'date',today,'reference','x','reason','overpayment'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Receipt exceeds agreement';end if;
 perform public.memocious_owner_order_action(sid,oid,3,gen_random_uuid(),'transition','{"status":"payment_received","reason":"Verified deposit permits work"}');
 perform public.memocious_owner_order_action(sid,oid,4,gen_random_uuid(),'transition','{"status":"on_hold","reason":"Waiting for choice"}');
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,5,gen_random_uuid(),'transition','{"status":"packed","reason":"Wrong resume"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Hold resumed into wrong state';end if;
 perform public.memocious_owner_order_action(sid,oid,5,gen_random_uuid(),'transition','{"status":"payment_received","reason":"Choice received"}');
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,6,gen_random_uuid(),'transition','{"status":"packed","reason":"Undocumented skip"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Production skipped without attestation';end if;
 perform public.memocious_owner_order_action(sid,oid,6,gen_random_uuid(),'transition','{"status":"quality_check","reason":"Ready-made inspected; no custom production","readyMadeVerified":true}');
 perform public.memocious_owner_order_action(sid,oid,7,gen_random_uuid(),'transition','{"status":"in_production","reason":"Quality failed; remake required"}');
 perform public.memocious_owner_order_action(sid,oid,8,gen_random_uuid(),'transition','{"status":"quality_check","reason":"Remake complete"}');
 perform public.memocious_owner_order_action(sid,oid,9,gen_random_uuid(),'transition','{"status":"packed","reason":"Quality passed"}');
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,10,gen_random_uuid(),'transition','{"status":"shipped","reason":"No dispatch adapter"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Dispatch prerequisite bypass';end if;
 perform public.memocious_owner_order_action(sid,oid,10,gen_random_uuid(),'transition','{"status":"cancelled","reason":"Agreed cancellation after deposit"}');
 readback:=public.memocious_owner_orders(sid,'GFT-2610-000001-0123456789AB');
 if readback->'order'->>'refundDue'<>'true' or readback->'order'->>'status'<>'cancelled' or readback->'order'->>'paymentReceivedPaise'<>'2000' or readback->'order'->>'refundRecordedPaise'<>'0' then raise exception 'Cancellation erased payment or inferred refund';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,11,gen_random_uuid(),'transition','{"status":"refunded","reason":"No money returned"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Status-only refund';end if;
 perform public.memocious_owner_order_action(sid,oid,11,gen_random_uuid(),'refund',jsonb_build_object('amountPaise',500,'date',today,'reference','refund first','reason','Verified offline partial return'));
 if public.memocious_owner_orders(sid,'GFT-2610-000001-0123456789AB')->'order'->>'status'<>'cancelled' then raise exception 'Partial refund became full';end if;
 key:=gen_random_uuid();r:=public.memocious_owner_order_action(sid,oid,12,key,'refund',jsonb_build_object('amountPaise',1500,'date',today,'reference','refund remainder','reason','Verified balance returned'));
 again:=public.memocious_owner_order_action(sid,oid,12,key,'refund',jsonb_build_object('amountPaise',1500,'date',today,'reference','refund remainder','reason','Verified balance returned'));
 if r<>again or r->>'status'<>'refunded' then raise exception 'Full refund/replay';end if;
 readback:=public.memocious_owner_orders(sid,'GFT-2610-000001-0123456789AB');
 if readback->'order'->>'refundDue'<>'false' or readback->'order'->>'paymentReceivedPaise'<>'2000' or readback->'order'->>'refundRecordedPaise'<>'2000' or jsonb_array_length(readback->'moneyRecords')<>3 then raise exception 'Payment history incorrect';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,oid,13,gen_random_uuid(),'transition','{"status":"inquiry","reason":"Reopen refunded"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Refund terminal bypass';end if;
 perform public.memocious_owner_order_action(sid,free_id,1,gen_random_uuid(),'transition','{"status":"confirmed","reason":"Agreed complimentary gift","agreedTotalPaise":0,"contactName":"Fixture","phone":"12025550123"}');
 perform public.memocious_owner_order_action(sid,free_id,2,gen_random_uuid(),'transition','{"status":"in_production","reason":"Zero total; no payment due"}');
 if public.memocious_owner_orders(sid,'GFT-2610-000002-0123456789AB')->'order'->>'paymentVerified'<>'false' then raise exception 'Zero total fabricated receipt';end if;
 failed:=false;begin perform public.memocious_owner_order_action(sid,free_id,3,gen_random_uuid(),'transition','{"status":"quality_check","reason":"x","paymentReceivedPaise":100}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Mass assignment';end if;
 execute 'reset role';
 if (select count(*) from memocious.order_events where order_id=oid)<>13 or (select count(*) from memocious.notification_outbox n join memocious.order_events e on e.id=n.event_id where e.order_id=oid)<>12 or (select count(*) from memocious.audit_log where entity_id=oid)<>12 then raise exception 'Event/audit/outbox not once per action';end if;
 if not exists(select 1 from memocious.audit_log where entity_id=oid and redacted_diff->>'readyMadeVerified'='true') then raise exception 'Ready-made attestation not retained';end if;
 if has_table_privilege('service_role','memocious.order_money_records','UPDATE,DELETE') or has_table_privilege('service_role','memocious.order_action_receipts','UPDATE,DELETE') then raise exception 'Offline record/receipt mutable';end if;
 update memocious_private.app_sessions set mfa_verified_at=now()-interval '6 minutes' where id=sid;
 execute 'set local role service_role';failed:=false;begin perform public.memocious_owner_order_action(sid,free_id,3,gen_random_uuid(),'transition','{"status":"quality_check","reason":"x"}');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Stale MFA action';end if;
 execute 'reset role';update memocious_private.app_sessions set mfa_verified_at=now() where id=sid;update memocious_private.admin_users set active=false where user_id=uid;
 execute 'set local role service_role';failed:=false;begin perform public.memocious_owner_orders(sid);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Revoked role';end if;execute 'reset role';
end $$;
rollback;
select 'PASS: owner recent-MFA actions, editor/customer/aal1/revoked denial, agreed zero, partial offline receipts, exact hold resume, ready-made/quality failure, dispatch prerequisite denial, paid cancellation/refund due, partial/full verified refunds, terminal state, persistent matching replay, stale/changed/mass-assignment denial and atomic event/audit/outbox counts' result;
